                    <li key={idx} style={{ marginBottom: 12, breakInside: 'avoid' }}>
                      <Link 
                        to={`/service/${item.toLowerCase().replace(/[ &/()]+/g, '-')}`}
                        style={{ 
                          color: '#b8c3d9', 
                          textDecoration: 'none',
                          fontSize: '13px',
                          transition: 'all 0.3s ease',
                          display: 'inline-block'
                        }}
                        onMouseEnter={(e) => {
                          e.currentTarget.style.color = '#d4af37';
                          e.currentTarget.style.transform = 'translateX(4px)';
                        }}
                        onMouseLeave={(e) => {
                          e.currentTarget.style.color = '#b8c3d9';
                          e.currentTarget.style.transform = 'translateX(0)';
                        }}
                      >
                        {item}
                      </Link>
                    </li>
                  ))}
                </ul>
              </div>
            </div>

            {/* Column 4 - Members & Partnership */}
            <div className='col-lg-3 col-md-6'>
              <div className='widget footer-widget'>
                <h3 className='widget-title' style={{ 
                  color: '#ffffff', 
                  fontSize: '18px', 
                  fontWeight: 600,
                  marginBottom: 20,
                  letterSpacing: '0.5px',
                  position: 'relative',
                  display: 'inline-block'
                }}>
                  Members of
                  <span style={{
                    position: 'absolute',
                    bottom: -8,
                    left: 0,
                    width: 40,
                    height: 2,
                    background: '#d4af37',
                    borderRadius: '2px'
                  }} />
                </h3>
                <ul className='footer-menu' style={{ display: 'flex', gap: 15, alignItems: 'center', marginTop: 20, flexWrap: 'wrap' }}>
                  <img
                    src={basis}
                    alt='site logo'
                    style={{
                      width: 130,
                      padding: '6px 12px',
                      backgroundColor: 'white',
                      borderRadius: 8,
                      objectFit: 'contain'
                    }}
                  />
                  <img
                    className='ms-3 ms-lg-0 margLg'
                    src={bacco}
                    alt='site logo'
                    style={{
                      width: 130,
                      padding: '6px 12px',
                      backgroundColor: 'white',
                      borderRadius: 8,
                      objectFit: 'contain'
                    }}
                  />
                </ul>
              </div>

              <div className='widget footer-widget' style={{ marginTop: 30 }}>
                <h3 className='widget-title' style={{ 
                  color: '#ffffff', 
                  fontSize: '18px', 
                  fontWeight: 600,
                  marginBottom: 20,
                  letterSpacing: '0.5px',
                  position: 'relative',
                  display: 'inline-block'
                }}>
                  Partnership
                  <span style={{
                    position: 'absolute',
                    bottom: -8,
                    left: 0,
                    width: 40,
                    height: 2,
                    background: '#d4af37',
                    borderRadius: '2px'
                  }} />
                </h3>
                <ul className='footer-menu' style={{ display: 'flex', gap: 15, alignItems: 'center', marginTop: 20, flexWrap: 'wrap' }}>
                  <img
                    src={cisco}
                    alt='site logo'
                    style={{
                      width: 130,
                      height: 70,
                      padding: '6px 12px',
                      backgroundColor: 'white',
                      borderRadius: 8,
                      objectFit: 'contain'
                    }}
                  />
                  <img
                    className='ms-3 ms-lg-0 margLg'
                    src={fort}
                    alt='site logo'
                    style={{
                      width: 130,
                      height: 70,
                      padding: '6px 12px',
                      backgroundColor: 'white',
                      borderRadius: 8,
                      objectFit: 'contain'
                    }}
                  />
                </ul>
              </div>
            </div>
          </div>
        </div>

        {/* Bottom Bar */}
        <div
          className='site-info'
          style={{ 
            fontSize: '12px',
            borderTop: '1px solid rgba(212, 175, 55, 0.2)',
            padding: '20px 0',
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
            flexWrap: 'wrap',
            gap: 12
          }}
        >
          <div className='copyright'>
            <p style={{ color: '#8a95b0', margin: 0 }}>
              © {CURRENT_YEAR} All Rights Reserved by{' '}
              <a
                href='https://suffixit.com/'
                target='_blank'
                style={{ color: '#d4af37', textDecoration: 'none', fontWeight: 500 }}
              >
                Suffix IT
              </a>
            </p>
          </div>
          <ul className='site-info-menu' style={{ 
            display: 'flex', 
            gap: 24, 
            listStyle: 'none', 
            margin: 0, 
            padding: 0 
          }}>
            <li>
              <a href='#' style={{ color: '#8a95b0', textDecoration: 'none', transition: 'color 0.3s' }} onMouseEnter={(e) => e.currentTarget.style.color = '#d4af37'} onMouseLeave={(e) => e.currentTarget.style.color = '#8a95b0'}>Privacy & Policy.</a>
            </li>
            <li>
              <a href='#' style={{ color: '#8a95b0', textDecoration: 'none', transition: 'color 0.3s' }} onMouseEnter={(e) => e.currentTarget.style.color = '#d4af37'} onMouseLeave={(e) => e.currentTarget.style.color = '#8a95b0'}>Faq.</a>
            </li>
            <li>
              <a href='#' style={{ color: '#8a95b0', textDecoration: 'none', transition: 'color 0.3s' }} onMouseEnter={(e) => e.currentTarget.style.color = '#d4af37'} onMouseLeave={(e) => e.currentTarget.style.color = '#8a95b0'}>Terms.</a>
            </li>
          </ul>
        </div>
      </div>
    </footer>
  );
};

export default Footer;
